('abide by', '/əˈbaɪd baɪ/', 'v', 'tuân thủ, tuân theo', 'All contractors must abide by the safety rules on site.', 'CONTRACTS (HỢP ĐỒNG)', 1, 'abide by', 'Tất cả nhà thầu phải tuân thủ các quy định an toàn tại công trường.', 'abide by', 'original', null, null),
('agreement', '/əˈɡriː.mənt/', 'n', 'sự thỏa thuận hợp đồng', 'Both companies signed the agreement after reviewing the payment terms.', 'CONTRACTS (HỢP ĐỒNG)', 2, 'agreement', 'Hai công ty đã ký thỏa thuận sau khi xem xét các điều khoản thanh toán.', 'agreement', 'original', null, null),
('assurance', '/əˈʃʊr.əns/', 'n', 'sự đảm bảo; lời cam đoan; sự tự tin', 'The supplier gave us assurance that the delivery would arrive on time.', 'CONTRACTS (HỢP ĐỒNG)', 3, 'assurance', 'Nhà cung cấp bảo đảm với chúng tôi rằng hàng sẽ được giao đúng hạn.', 'assurance', 'original', 'Cambridge xếp assurance là danh từ; PDF ghi thêm loại động từ.', 'https://dictionary.cambridge.org/us/dictionary/english/assurance'),
('cancellation', '/ˌkæn.səlˈeɪ.ʃən/', 'n', 'sự hủy bỏ, chấm dứt (n)', 'Please request cancellation before Friday to receive a full refund.', 'CONTRACTS (HỢP ĐỒNG)', 4, 'cancellation', 'Vui lòng yêu cầu hủy trước thứ Sáu để được hoàn tiền đầy đủ.', 'cancellation', 'original', null, null),
('determine', '/dɪˈtɜːrmɪn/', 'v', 'xác định', 'The inspection will determine whether the equipment needs urgent repairs.', 'CONTRACTS (HỢP ĐỒNG)', 5, 'determine', 'Cuộc kiểm tra sẽ xác định liệu thiết bị có cần sửa chữa khẩn cấp hay không.', 'determine', 'original', null, null),
('engage', '/ɪnˈɡeɪdʒ/', 'v', 'tham dự', 'New employees can engage in discussions during the orientation workshop.', 'CONTRACTS (HỢP ĐỒNG)', 6, 'engage', 'Nhân viên mới có thể tham gia thảo luận trong buổi hướng dẫn hội nhập.', 'engage', 'original', null, null),
('establish', '/ɪˈstæblɪʃ/', 'v', 'thành lập, thiết lập', 'Our partners plan to establish a regional office next spring.', 'CONTRACTS (HỢP ĐỒNG)', 7, 'establish', 'Các đối tác của chúng tôi dự định thành lập văn phòng khu vực vào mùa xuân tới.', 'establish', 'original', null, null),
('obligate', '/ˈɑːblɪɡeɪt/', 'v', 'bắt buộc', 'These terms obligate the buyer to pay within thirty days.', 'CONTRACTS (HỢP ĐỒNG)', 8, 'obligate', 'Những điều khoản này buộc bên mua phải thanh toán trong vòng ba mươi ngày.', 'obligate', 'original', null, null),
('party', '/ˈpɑːrti/', 'n', 'bên (trong các tổ chức)', 'Each party must keep a signed copy of the contract.', 'CONTRACTS (HỢP ĐỒNG)', 9, 'party', 'Mỗi bên phải giữ một bản hợp đồng đã ký.', 'party', 'original', null, null),
('provision', '/prəˈvɪʒ.ən/', 'n', 'sự cung cấp/ điều khoản', 'This provision allows customers to return damaged goods without charge.', 'CONTRACTS (HỢP ĐỒNG)', 10, 'provision', 'Điều khoản này cho phép khách hàng trả lại hàng hỏng mà không mất phí.', 'provision', 'original', null, null),
('resolve', '/rɪˈzɔːlv/', 'v', 'giải quyết, quyết định', 'The manager will resolve the billing dispute before the deadline.', 'CONTRACTS (HỢP ĐỒNG)', 11, 'resolve', 'Người quản lý sẽ giải quyết tranh chấp hóa đơn trước thời hạn.', 'resolve', 'original', null, null),
('specific', '/spəˈsɪf.ɪk/', 'adj', 'cụ thể', 'Please provide specific instructions for installing the new payment terminal.', 'CONTRACTS (HỢP ĐỒNG)', 12, 'specific', 'Vui lòng cung cấp hướng dẫn cụ thể để lắp đặt thiết bị thanh toán mới.', 'specific', 'original', null, null),
('attract', '/əˈtrækt/', 'v', 'thu hút, hấp dẫn', 'The colorful window display should attract more customers this weekend.', 'MARKETING (TIẾP THỊ)', 13, 'attract', 'Cách trưng bày đầy màu sắc ở cửa sổ sẽ thu hút thêm khách hàng cuối tuần này.', 'attract', 'original', null, null),
('compare', '/kəmˈper/', 'v', 'so sánh, đối chiếu', 'We should compare delivery fees before choosing an online supplier.', 'MARKETING (TIẾP THỊ)', 14, 'compare', 'Chúng ta nên so sánh phí giao hàng trước khi chọn nhà cung cấp trực tuyến.', 'compare', 'original', null, null),
('competition', '/ˌkɑːm.pəˈtɪʃ.ən/', 'n', 'sự cạnh tranh/ cuộc thi', 'Strong competition has encouraged local retailers to improve their service.', 'MARKETING (TIẾP THỊ)', 15, 'competition', 'Sự cạnh tranh mạnh mẽ đã khuyến khích các nhà bán lẻ địa phương cải thiện dịch vụ.', 'competition', 'original', null, null),
('consume', '/kən’sju:m/', 'v', 'tiêu thụ, sử dụng', 'Older printers consume more electricity than the models we ordered.', 'MARKETING (TIẾP THỊ)', 16, 'consume', 'Máy in cũ tiêu thụ nhiều điện hơn những mẫu chúng tôi đã đặt.', 'consume', 'original', null, null),
('convince', '/kənˈvɪns/', 'v', 'thuyết phục', 'The sales team hopes to convince customers to renew their subscriptions.', 'MARKETING (TIẾP THỊ)', 17, 'convince', 'Đội ngũ bán hàng hy vọng thuyết phục khách hàng gia hạn các gói đăng ký.', 'convince', 'original', null, null),
('inspiration', '/ˌɪn.spəˈreɪ.ʃən/', 'n', 'nguồn cảm hứng', 'Customer feedback provided the inspiration for our latest advertising campaign.', 'MARKETING (TIẾP THỊ)', 18, 'inspiration', 'Phản hồi của khách hàng mang lại cảm hứng cho chiến dịch quảng cáo mới nhất của chúng tôi.', 'inspiration', 'original', null, null),
('market', '/ˈmɑːrkɪt/', 'v, n', 'buôn bán (v) thị trường (n)', 'The company entered the overseas market after extensive consumer research.', 'MARKETING (TIẾP THỊ)', 19, 'market', 'Công ty đã gia nhập thị trường nước ngoài sau khi nghiên cứu người tiêu dùng kỹ lưỡng.', 'market', 'original', null, null),
('persuasion', '/pəˈsweɪ.ʒən/', 'n', 'sự thuyết phục', 'It took considerable persuasion to secure approval for the revised budget.', 'MARKETING (TIẾP THỊ)', 20, 'persuasion', 'Phải thuyết phục rất nhiều mới được phê duyệt ngân sách đã điều chỉnh.', 'persuasion', 'original', null, null),
('productive', '/prəˈdʌk.tɪv/', 'adj', 'năng suất | có hiệu quả, có năng suất', 'Our morning meeting was productive because everyone arrived fully prepared.', 'MARKETING (TIẾP THỊ) | PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 21, 'productive', 'Cuộc họp sáng của chúng tôi hiệu quả vì mọi người đều đến với sự chuẩn bị đầy đủ.', 'productive', 'original', null, null),
