('attend', '/əˈtend/', 'v', 'tham gia, tham dự', 'Please confirm whether you can attend the annual sales conference.', 'CONFERENCES (HỘI NGHỊ)', 50, 'attend', 'Vui lòng xác nhận liệu bạn có thể tham dự hội nghị bán hàng hằng năm hay không.', 'attend', 'original', null, null),
('get in touch + with somebody', null, 'v', 'liên lạc với ai, kết nối với ai (= connect)', 'Please get in touch with our coordinator to discuss dietary requirements.', 'CONFERENCES (HỘI NGHỊ)', 51, 'get in touch with', 'Vui lòng liên lạc với điều phối viên của chúng tôi để trao đổi yêu cầu về ăn uống.', 'get in touch with', 'original', null, null),
('hold', '/həʊld/', 'v', 'tiến hành, tổ chức/ chứa, đựng (= contain)', 'The company will hold its regional conference in Hanoi this year.', 'CONFERENCES (HỘI NGHỊ)', 52, 'hold', 'Công ty sẽ tổ chức hội nghị khu vực tại Hà Nội năm nay.', 'hold', 'original', null, null),
